#!/usr/bin/env node
/**
 * Generates src/data/serves.ts — the list of surrounding towns within ~50 miles
 * of each city that has listings. This is the "expand the city page border"
 * data: a suburban visitor (e.g. Everett) is told which metro covers them.
 *
 * Towns are auto-generated from a radius via the Overpass API (place=city|town|suburb
 * around the city centroid, sorted by population) rather than hand-curated.
 *
 * Usage:
 *   node scripts/build-serves.mjs
 */

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, '..');
const GEO_JSON = path.join(ROOT, 'public', 'listings.geo.json');
const OUT = path.join(ROOT, 'src', 'data', 'serves.ts');

const RADIUS_M = 80000; // ~50 miles
const MAX_TOWNS = 8;
const ANCHOR_EXCLUDE_MI = 3; // drop the city's own node at ~0 distance
const UA = 'sounddip-coverage/1.0 (contact: hello@sounddip.com)';

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

function milesBetween(a, b) {
  const R = 3958.8;
  const toRad = (d) => (d * Math.PI) / 180;
  const dLat = toRad(b.lat - a.lat);
  const dLng = toRad(b.lng - a.lng);
  const h =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(toRad(a.lat)) * Math.cos(toRad(b.lat)) * Math.sin(dLng / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(h));
}

async function nearbyTowns(lat, lng) {
  const q = `[out:json][timeout:60];(node["place"~"city|town|suburb"](around:${RADIUS_M},${lat},${lng}););out body 200;`;
  let lastErr;
  for (let attempt = 1; attempt <= 3; attempt++) {
    try {
      const res = await fetch('https://overpass-api.de/api/interpreter', {
        method: 'POST',
        headers: {
          Accept: 'application/json',
          'User-Agent': UA,
          'Content-Type': 'application/x-www-form-urlencoded',
        },
        body: new URLSearchParams({ data: q }),
      });
      if (res.status === 429) {
        lastErr = new Error('Overpass 429 rate limited');
        await sleep(5000 * attempt);
        continue;
      }
      if (!res.ok) throw new Error(`Overpass HTTP ${res.status}`);
      const data = await res.json();
      return (data.elements || [])
        .map((e) => ({
          name: e.tags?.name,
          place: e.tags?.place,
          pop: parseInt(e.tags?.population || '0', 10) || 0,
          dist: milesBetween(
            { lat, lng },
            { lat: e.lat ?? e.center?.lat, lng: e.lon ?? e.center?.lon },
          ),
        }))
        .filter((e) => e.name && e.dist >= ANCHOR_EXCLUDE_MI)
        .sort((a, b) => b.pop - a.pop);
    } catch (err) {
      lastErr = err;
      await sleep(3000 * attempt);
    }
  }
  throw lastErr || new Error('Overpass failed');
}

function readCities() {
  const g = JSON.parse(fs.readFileSync(GEO_JSON, 'utf8'));
  const bySlug = {};
  for (const l of g) (bySlug[l.citySlug] ||= []).push(l);
  return Object.entries(bySlug).map(([slug, listings]) => {
    const n = listings.length;
    return {
      slug,
      name: listings[0].city,
      lat: listings.reduce((s, l) => s + l.lat, 0) / n,
      lng: listings.reduce((s, l) => s + l.lng, 0) / n,
    };
  });
}

async function main() {
  const cities = readCities();
  const serves = {};
  let failed = 0;
  for (const city of cities) {
    try {
      const towns = await nearbyTowns(city.lat, city.lng);
      serves[city.slug] = towns.slice(0, MAX_TOWNS).map((t) => t.name);
      console.log(`  ✓ ${city.slug.padEnd(18)} ${serves[city.slug].join(', ') || '(none)'}`);
    } catch (err) {
      failed++;
      serves[city.slug] = [];
      console.error(`  ✗ ${city.slug}: ${err.message}`);
    }
    await sleep(1500);
  }

  const header =
    '// Auto-generated by scripts/build-serves.mjs. Nearby towns within ~50 miles\n' +
    '// of each city center (Overpass place=city|town|suburb, sorted by population).\n' +
    '// Do not hand-edit — regenerate with `node scripts/build-serves.mjs`.\n';
  const body = `export const servesByCity: Record<string, string[]> = ${JSON.stringify(serves, null, 2)};\n`;
  fs.writeFileSync(OUT, header + body);
  console.log(`\nWrote ${Object.keys(serves).length} cities to src/data/serves.ts`);
  if (failed) {
    console.error(`${failed} cities failed — serves.ts is incomplete, do not deploy.`);
    process.exit(1);
  }
}

main();
